export function getPostBySlug(slug: string): Post | undefined {
  return posts.find((p) => p.slug === slug);
}

export function getRelatedPosts(post: Post, count = 3): Post[] {
  const sameCat = posts.filter((p) => p.slug !== post.slug && p.category === post.category).slice(0, count);
  return sameCat.length > 0 ? sameCat : posts.filter((p) => p.slug !== post.slug).slice(0, count);
}
